// === 自定义 Loader：markdown 转 HTML ===
// markdown-loader.js
const { marked } = require('marked');

/** @type {import('webpack').LoaderDefinitionFunction} */
module.exports = function (source) {
  // this.getOptions() 获取 loader options（Webpack 5 推荐方式，替代 loader-utils）
  const options = this.getOptions();
  const html = marked(source, options);
  // 必须返回合法 JS 模块代码
  return `export default ${JSON.stringify(html)}`;
};

// === 自定义 Plugin：构建完成后输出报告 ===
// build-report-plugin.js
class BuildReportPlugin {
  apply(compiler) {
    // compiler.hooks.done 是 AsyncSeriesHook，构建完成后触发
    compiler.hooks.done.tap('BuildReportPlugin', (stats) => {
      const { errors, warnings, assets, time } = stats.toJson({
        errors: true, warnings: true, assets: true, time: true
      });
      console.log(`\n--- Build Report ---`);
      console.log(`Duration: ${time}ms`);
      console.log(`Assets: ${assets.length}`);
      console.log(`Errors: ${errors.length}, Warnings: ${warnings.length}`);
      if (errors.length > 0) {
        errors.forEach(err => console.error(err.message));
      }
    });

    // 在 emit 阶段注入额外文件
    compiler.hooks.emit.tapAsync('BuildReportPlugin', (compilation, callback) => {
      const report = JSON.stringify({
        buildTime: Date.now(),
        assets: Object.keys(compilation.assets)
      }, null, 2);
      // compilation.assets 是即将输出的文件列表
      compilation.assets['build-report.json'] = {
        source: () => report,
        size: () => report.length
      };
      callback();
    });
  }
}

// === webpack.config.js 关键配置 ===
const path = require('path');
const HtmlWebpackPlugin = require('html-webpack-plugin');
const MiniCssExtractPlugin = require('mini-css-extract-plugin');

module.exports = {
  mode: 'production',
  entry: './src/index.js',
  output: {
    filename: '[name].[contenthash:8].js',
    path: path.resolve(__dirname, 'dist'),
    clean: true
  },
  // Webpack 5 持久化缓存，二次构建极快
  cache: {
    type: 'filesystem',
    buildDependencies: {
      config: [__filename] // webpack.config.js 变化时缓存失效
    }
  },
  module: {
    rules: [
      {
        test: /\.js$/,
        exclude: /node_modules/,
        use: [
          // thread-loader 放在 babel-loader 前面，把编译放到 worker 线程
          // 注意：worker 有启动开销，只在编译耗时 > 300ms 时才有收益
          // 'thread-loader',
          'babel-loader'
        ]
      },
      {
        test: /\.css$/,
        use: [MiniCssExtractPlugin.loader, 'css-loader', 'postcss-loader']
      },
      {
        test: /\.(png|jpg|gif)$/,
        type: 'asset/resource',
        generator: { filename: 'images/[hash:8][ext]' }
      }
    ]
  },
  plugins: [
    new HtmlWebpackPlugin({ template: './src/index.html' }),
    new MiniCssExtractPlugin({ filename: 'css/[name].[contenthash:8].css' }),
    new BuildReportPlugin()
  ],
  optimization: {
    splitChunks: {
      chunks: 'all', // initial + async chunk 都参与分割
      minSize: 20000, // 至少 20KB 才提取
      maxSize: 244000, // 超过 244KB 的 chunk 再拆（适合 HTTP/2）
      cacheGroups: {
        vendor: {
          test: /[\\/]node_modules[\\/]/,
          name: 'vendors',
          chunks: 'all',
          priority: 10
        },
        common: {
          minChunks: 2, // 被 2+ chunk 引用的模块提取到 common
          name: 'common',
          chunks: 'all',
          reuseExistingChunk: true,
          priority: 5
        }
      }
    },
    // Webpack 5 生产模式自动启用 TerserPlugin
    // minimizer: [new TerserPlugin({ parallel: true })]
  },
  devServer: {
    hot: true,
    port: 3000
  }
};

